from common_l2 import *
from numeric_core import solve,solve_many,certificate,hessian_template
import resource,subprocess,scipy

def main():
 tests=load(HERE/'analysis/solver_test_integrity.json');assert tests['status']=='PASS_SYNTHETIC_CERTIFICATES' and tests['immutable_length_only_cache_hit_miss_verified'];assert load(HERE/'analysis/legacy_counterexample_reproduction.json')['status']=='PASS_REPRODUCED'
 p=HERE/'configs/solver_production_v1.json';assert not p.exists();config=dict(algorithm='independent_dual_log_barrier_newton_v1',lambda_fixed=50.,dtype='float64',max_newton_iterations=600,max_barrier_stages=30,barrier_reduction=.1,line_search_steps=60,step_fraction=.995,initial_q='zeros for each axis',initial_mu='max(E_aff/(2*(T-2)),1e-12) each axis only',gap_rule='1e-8+1e-4*E_aff',E_aff='.5*sum((y-x_aff)**2)',negative_gap_rule='64eps64*(1+abs(P)+abs(D)+sumabs(y*v)+50sumabs(x))',failure_policy='FAIL; no fallback; no training-ready marker',matrix_cache='immutable length-only D2D2T pattern; no record values',production_reason='per-axis fixedrho40 ADMM reference still fails certificate at30k; estimated lower bound30601.8CPU s exceeds21600; barrier crosschecks pass',numpy=np.__version__,scipy=scipy.__version__);write(p,config)
 source=HERE/'scripts/numeric_core.py';freeze('PRODUCTION_SOLVER_V1',[source,p,HERE/'scripts/pilot_l2.py',HERE/'PROTOCOL.md',HERE/'PROTOCOL_AMENDMENT.md'],classification_results_seen=False,only_production_algorithm=config['algorithm'])
 protected=load(PRIVATE/'manifests/protected_assets.json')['sha256'];selected=[]
 for activity in ACTS:selected+=sorted([r for r in records() if r['activity']==activity],key=lambda r:protected[r['raw_path']])[:2]
 write(PRIVATE/'manifests/pilot_selection.json',dict(rule='before signal solving: first2rawSHA peractivity; no label or model outcome selection',records=selected,for_training=False))
 rows=[];recordcost=[];maxdiff=0.;opts={k:config[k] for k in ['max_newton_iterations','max_barrier_stages','barrier_reduction','line_search_steps','step_fraction']};first=True;start=time.process_time();output=PRIVATE/'subject_diagnostics/pilot';output.mkdir(parents=True,exist_ok=False)
 for k,r in enumerate(selected):
  beg=time.process_time();path=Path(r['raw_path']);assert sha(path)==protected[str(path)];raw=np.loadtxt(path,delimiter=',',dtype=float);y=raw[:,1:4].T;tr,q,certs=solve_many(y,opts)
  if not all(c['passed'] for c in certs):write(output/f'failure_{k}.json',dict(record=r,certificates=certs));raise RuntimeError('BLOCKED_PILOT_CERTIFICATE')
  separate=np.stack([solve(axis,opts)[0] for axis in y]);reorder=solve_many(y[[2,0,1]],opts)[0][[1,2,0]];hessian_template.cache_clear();cold=solve_many(y,opts)[0];delta=max(abs(tr-separate).max(),abs(tr-reorder).max(),abs(tr-cold).max());maxdiff=max(maxdiff,float(delta));assert delta<=1e-7
  residual=y-tr;assert abs(y-tr-residual).max()<=5e-13*(1+abs(y).max());processed=np.vstack([residual[:,48:],raw[48:,4:7].T]).astype(np.float32);assert processed.shape==(6,len(raw)-48) and np.array_equal(processed[3:],raw[48:,4:7].T.astype(np.float32));quant=abs(processed[:3].astype(float)-residual[:,48:]);bound=abs(np.spacing(processed[:3])).astype(float)+8*np.finfo(float).eps*(1+abs(residual).max());assert np.all(quant<=bound)
  np.save(output/f'signal_{k}.npy',processed,allow_pickle=False);assert np.array_equal(np.load(output/f'signal_{k}.npy',allow_pickle=False),processed)
  np.savez_compressed(output/f'certificate_{k}.npz',trend=tr,dual=np.stack(q));write(output/f'certificate_{k}.json',dict(record=r,source_sha256=sha(source),config_sha256=sha(p),certificates=certs,quantization_max=float(quant.max()),PILOT_ONLY_NOT_FOR_TRAINING=True))
  for axis,c in enumerate(certs):rows.append(dict(case_index=k,raw_length=len(raw),axis=axis,**c))
  old=np.load(r['processed_path'],allow_pickle=False);recordcost.append(dict(case_index=k,raw_length=len(raw),record_CPU_seconds=time.process_time()-beg,maximum_saved_quantization_error=float(quant.max()),signal_difference_RMS=float(np.sqrt(np.mean((processed[:3].astype(float)-old[:3])**2))),peak_process_RSS_KiB=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss))
  if first:
   first=False;np.save(output/'restart_input.npy',y,allow_pickle=False);code="import sys,numpy as np;from pathlib import Path;sys.path.insert(0,'"+str(HERE/'scripts')+"');from numeric_core import solve_many;p=Path('"+str(output)+"');np.save(p/'restart_output.npy',solve_many(np.load(p/'restart_input.npy',allow_pickle=False))[0],allow_pickle=False)";subprocess.run([sys.executable,'-B','-c',code],check=True);assert abs(tr-np.load(output/'restart_output.npy',allow_pickle=False)).max()<=1e-7
  print(json.dumps(dict(stage='pilot',completed=k+1,total=22,raw_length=len(raw),certificate_count=len(rows))),flush=True)
 frame=pd.DataFrame(rows);cost=pd.DataFrame(recordcost);frame.to_csv(output/'axis_certificates.csv',index=False);cost.to_csv(output/'record_costs.csv',index=False)
 cpu95=float(frame.cpu_seconds.quantile(.95));projection=2*cpu95*25740+max(0,float(cost.record_CPU_seconds.mean())-3*float(frame.cpu_seconds.mean()))*8580
 spent=load(PRIVATE/'manifests/cpu_ledger.json')['total_solver_CPU_seconds'];remaining=21600-spent-(time.process_time()-start);state='PASS_PILOT_AND_BUDGET' if projection<remaining*.9 else 'BLOCKED_COMPUTE_BUDGET'
 pd.DataFrame([dict(stage='pilot',wrist_records=22,axes=66,certificate_pass_count=int(frame.passed.sum()),maximum_gap_ratio=float((frame.raw_gap/frame.gap_tolerance).max()),minimum_raw_gap=float(frame.raw_gap.min()),single_batch_reorder_restart_max_abs=maxdiff,axis_CPU_median=frame.cpu_seconds.median(),axis_CPU_p95=cpu95,record_CPU_mean=cost.record_CPU_seconds.mean(),estimated_full_export_CPU_seconds_conservative=projection,remaining_CPU_budget_seconds=remaining,peak_process_RSS_KiB=int(cost.peak_process_RSS_KiB.max()),data_summaries_private=True)]).to_csv(HERE/'analysis/pilot_summary.csv',index=False)
 write(HERE/'analysis/pilot_integrity.json',dict(status=state,records=22,axes=66,all_certificates_pass=True,both_raw_lengths=sorted(frame.raw_length.unique().tolist()),record_independence_max_abs=maxdiff,production_source_sha256=sha(source),production_config_sha256=sha(p),production_config=str(p),CPU_projection_seconds=projection,budget_remaining_before_complete_export=remaining,normalization_refits=0,classification_results_seen=False));print(json.dumps(dict(status=state,full_export_estimated_CPU_seconds=projection)))
 if state!='PASS_PILOT_AND_BUDGET':raise RuntimeError(state)
if __name__=='__main__':main()
